  color: {domain: ["regresión", "extremos"], range: [COLORES.rojo, COLORES.ambar], legend: true},
  marks: [
    Plot.line(demandaD.regresion, {x: "anio", y: "valor", stroke: () =&gt; "regresión", strokeWidth: 2.2}),
    Plot.line(demandaD.extremos, {x: "anio", y: "valor", stroke: () =&gt; "extremos", strokeDasharray: "5 4", strokeWidth: 2}),
    Plot.dot(demandaD.puntos, {x: "anio", y: "valor", fill: COLORES.azul, r: 4}),
