  const nombres = {retardo_constructor_firme: "retardo constructor", sensibilidad_precio: "sensibilidad del precio", elasticidad_inversion: "elasticidad de inversión", crecimiento_demanda: "crecimiento de la demanda", vida_util_firme: "vida útil firme", tasa_aprendizaje: "tasa de aprendizaje"};
  const fncer = metricaT.startsWith("capacidad");
  const extra = fncer ? {subasta_fncer: 300} : {};
  const medir = (parametros) =&gt; {
    const r = simular(mercadoConPoliticas({...caso, ...extra, ...parametros}), {tFinal: 40, paso: 0.05});
    if (fncer) return r.variables.capacidad_fncer.at(-1);
    const m = r.variables.margen_reserva.filter((_, k) =&gt; r.tiempo[k] &gt;= 5);
    return metricaT.startsWith("amplitud") ? Math.max(...m) - Math.min(...m) : Math.min(...m);
  };
  const base = medir({});
  const f = rangoT / 100;
  const filas = Object.keys(caso).map((p) =&gt; {
    const bajo = medir({[p]: caso[p] * (1 - f)}), alto = medir({[p]: caso[p] * (1 + f)});
    return {parametro: nombres[p], bajo, alto, ancho: Math.abs(alto - bajo)};
  }).sort((a, b) =&gt; b.ancho - a.ancho);
  const formato = fncer ? (x) =&gt; `${formatoNumero(0)(x)} MW` : (x) =&gt; formatoPorcentaje(x, 2);
  return {base, filas, formato, fncer};
}









