vulnerabilidadV = {
  const f = futurosV.futuros;
  const puntos = futurosV.costos.map((c, i) =&gt; {
    const arrepentimiento = c[2] - Math.min(...c);
    return {aprendizaje: f.tasa_aprendizaje[i], canibalizacion: f.canibalizacion[i], arrepentimiento,
      falla: arrepentimiento &gt; umbralV,
      enCaja: f.tasa_aprendizaje[i] &lt; aprendizajeV && f.canibalizacion[i] &gt; canibalizacionV};
  });
  const fallas = puntos.filter((p) =&gt; p.falla).length;
  const enCaja = puntos.filter((p) =&gt; p.enCaja).length;
  const fallasEnCaja = puntos.filter((p) =&gt; p.falla && p.enCaja).length;
  const peor = puntos.reduce((a, p) =&gt; (p.arrepentimiento &gt; a.arrepentimiento ? p : a));
  return {puntos, fallas, enCaja, fallasEnCaja, peor,
    cobertura: fallas ? fallasEnCaja / fallas : 0, densidad: enCaja ? fallasEnCaja / enCaja : 0};
}









